 "content": "def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    marker = next((v for row in grid for v in row if v != grid[0][0]), None)
    if marker is None:
        return out

    # Fill spaces between consecutive markers on each row and column.
    for r in range(h):
        marks = [c for c in range(w) if grid[r][c] == marker]
        for a, b in zip(marks, marks[1:]):
            for c in range(a + 1, b):
                out[r][c] = 3
    for c in range(w):
        marks = [r for r in range(h) if grid[r][c] == marker]
        for a, b in zip(marks, marks[1:]):
            for r in range(a + 1, b):
                out[r][c] = 3
    return out
